        let parts: Vec<string> = line.trim().split(" ").map(|s| s.to_string()).collect()
        if parts[0] == "" { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if root < 0 {
                keys.push(x)
                lf.push(-1)
                rt.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur: int = root
                let mut found = false
                let mut go = true
                while go {
                    let k = keys[cur as usize]
                    if x == k {
                        found = true
                        go = false
                    } else if x < k {
                        let n = lf[cur as usize]
                        if n < 0 {
                            let id: int = keys.len() as int
                            keys.push(x)
                            lf.push(-1)
                            rt.push(-1)
                            lf[cur as usize] = id
                            go = false
                        } else {
                            cur = n
                        }
                    } else {
                        let n = rt[cur as usize]
                        if n < 0 {
                            let id: int = keys.len() as int
                            keys.push(x)
                            lf.push(-1)
                            rt.push(-1)
                            rt[cur as usize] = id
                            go = false
                        } else {
                            cur = n
                        }
                    }
                }
                if found { println("dup") } else { println("ok") }
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: int = root
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = lf[cur as usize]
                } else {
                    cur = rt[cur as usize]
                }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: int = root
            let mut par: int = -1
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else {
                    par = cur
                    if x < k { cur = lf[cur as usize] } else { cur = rt[cur as usize] }
                }
            }
            if !found {
                println("missing")
            } else {
                let l = lf[cur as usize]
                let r = rt[cur as usize]
                if l >= 0 && r >= 0 {
                    let mut sp = cur
                    let mut s = r
                    while lf[s as usize] >= 0 {
                        sp = s
                        s = lf[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    let sr = rt[s as usize]
                    if sp == cur {
                        rt[sp as usize] = sr
                    } else {
                        lf[sp as usize] = sr
                    }
                } else {
                    let child = if l >= 0 { l } else { r }
                    if par < 0 {
                        root = child
                    } else if lf[par as usize] == cur {
                        lf[par as usize] = child
                    } else {
                        rt[par as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            let mut stack: Vec<int> = []
            let mut cur: int = root
            while cur >= 0 || stack.len() > 0 {
                while cur >= 0 {
                    stack.push(cur)
                    cur = lf[cur as usize]
                }
                let n = stack.pop().unwrap_or(0)
                out.push("${keys[n as usize]}")
                cur = rt[n as usize]
            }
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            let mut h = 0
            let mut level: Vec<int> = []
            if root >= 0 { level.push(root) }
            while level.len() > 0 {
                h += 1
                let mut next: Vec<int> = []
                for n in level {
                    if lf[n as usize] >= 0 { next.push(lf[n as usize]) }
                    if rt[n as usize] >= 0 { next.push(rt[n as usize]) }
                }
                level = next
            }
            println("${h}")
        } else if cmd == "min" || cmd == "max" {
            if root < 0 {
                println("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while lf[cur as usize] >= 0 { cur = lf[cur as usize] }
                } else {
                    while rt[cur as usize] >= 0 { cur = rt[cur as usize] }
                }
                println("${keys[cur as usize]}")
            }
